<!-- This file is generated by AI. -->
<!--
  统一模态框外壳: 遮罩、标题行、主体与底部操作栏。

  三条设计约束: **不使用 portal** —— 层级完全在应用 DOM 内, 规避 WebView 里弹层的定位/动画
  异常; **Esc 只关最上层** —— 判据是文档里除我以外还有没有别的 `.modal-surface`, 只看自己的
  子树会漏判 (应用级确认框与调用它的对话框是兄弟节点), 也不响应输入法组合键
  (`event.isComposing`: 中文输入时 Esc 是取消候选); **只做行为不做外观** —— 配色/圆角/内边距
  全部来自 `styles.css` 的 `.modal-*` / `.dialog-*` 规则。
-->
<script lang="ts">
  import type { Snippet } from 'svelte';
  import { fade, fly } from 'svelte/transition';

  import Icon from './Icon.svelte';
  import type { IconName } from './icons';

  let {
    title,
    iconName,
    /** 标题下方的补充说明 */
    description,
    /** 尺寸档位, 对应 styles.css 的 `.dialog-<size>` */
    size = 'medium',
    /** 主体固定高度 (px), 省略则由内容决定 */
    height,
    /** 紧凑模式: 内部有滚动列表时让它占满剩余高度 */
    compact = false,
    /** 主体不加内边距与间距, 由内容自己排布 */
    flush = false,
    /** 追加的类名 (调用方需要额外样式时用) */
    className = '',
    /** 点击遮罩是否关闭 */
    closeOnBackdrop = true,
    /** 标题行右侧的额外内容 */
    titleExtra,
    /** 底部按钮区左侧的内容 (如"不再提示") */
    footerLeading,
    /** 底部按钮区 */
    footer,
    onClose,
    children,
  }: {
    title: string;
    iconName?: IconName;
    description?: string;
    size?: 'small' | 'form' | 'medium' | 'large';
    height?: number;
    compact?: boolean;
    flush?: boolean;
    className?: string;
    closeOnBackdrop?: boolean;
    titleExtra?: Snippet;
    footerLeading?: Snippet;
    footer?: Snippet;
    onClose: () => void;
    children: Snippet;
  } = $props();

  const surfaceClass = $derived(
    [
      'modal-surface',
      'dialog-surface',
      `dialog-${size}`,
      compact ? 'dialog-compact' : '',
      flush ? 'dialog-flush' : '',
      className,
    ]
      .filter(Boolean)
      .join(' ')
  );

  /**
   * 我上面还有没有别的对话框。
   *
   * 判据是文档级的: 应用级确认框由 `confirm.ts` / `unsaved.ts` 的单例渲染在应用根, 与调用它的
   * 对话框是**兄弟**节点, 只看自己的子树会漏判, 于是 Esc 会把整叠一起关掉。
   */
  function hasNestedDialog(): boolean {
    return document.querySelectorAll('.modal-surface').length > 1;
  }

  function handleKeydown(event: KeyboardEvent) {
    if (event.key !== 'Escape' || event.isComposing) return;
    if (hasNestedDialog()) return;
    event.stopPropagation();
    onClose();
  }

  /** 点遮罩关闭: 只有 `target === currentTarget` 才算"点外面", 内层面板因此不必挂点击处理器 (会触发 a11y 警告)。 */
  function handleBackdropClick(event: MouseEvent) {
    if (event.target !== event.currentTarget) return;
    if (!closeOnBackdrop || hasNestedDialog()) return;
    onClose();
  }
</script>

<svelte:window onkeydown={handleKeydown} />

<!-- 内层面板不挂点击处理器: "点内部不关闭"由 `handleBackdropClick` 判目标完成 -->
<div
  class="modal-backdrop"
  role="presentation"
  transition:fade={{ duration: 120 }}
  onclick={handleBackdropClick}
  onkeydown={(event) => {
    // 键盘用户的 Esc, 与 window 上那个监听同一判据
    if (event.key === 'Escape') handleKeydown(event);
  }}
>
  <div
    class={surfaceClass}
    style={height === undefined ? undefined : `height:${height}px`}
    role="dialog"
    aria-modal="true"
    aria-label={title}
    tabindex="-1"
    transition:fly={{ y: 8, duration: 160 }}
  >
    <header class="dialog-head">
      {#if iconName}
        <span class="dialog-head-icon" aria-hidden="true"><Icon name={iconName} size={20} /></span>
      {/if}
      <div class="dialog-head-text">
        <h2 class="dialog-title">{title}</h2>
        {#if description}<p class="dialog-description">{description}</p>{/if}
      </div>
      {#if titleExtra}<div class="dialog-title-extra">{@render titleExtra()}</div>{/if}
    </header>

    <div class="dialog-body">
      {@render children()}
    </div>

    <!-- 底部操作栏只在调用方真的给了内容时才渲染: 无条件渲染会留一条带 `border-top` 的空横条 -->
    {#if footer || footerLeading}
      <footer class="dialog-foot">
        <div class="dialog-foot-leading">
          {#if footerLeading}{@render footerLeading()}{/if}
        </div>
        <div class="dialog-foot-actions">
          {#if footer}{@render footer()}{/if}
        </div>
      </footer>
    {/if}
  </div>
</div>
